package main

import (
	"fmt"
	"testing"

	assert "github.com/stretchr/testify/require"
)

func getDefaultOptions() *options {
	return &options{
		httpPort:  -1,
		httpsPort: -1,
		port:      -1,
	}
}

func TestCheckConflictingOptions(t *testing.T) {
	//
	// Valid sets of options (not exhaustive, but included quite a few standard invocations)
	//

	{
		options := getDefaultOptions()
		options.http = true

		err := options.checkConflictingOptions()
		assert.NoError(t, err)
	}

	{
		options := getDefaultOptions()
		options.https = true

		err := options.checkConflictingOptions()
		assert.NoError(t, err)
	}

	{
		options := getDefaultOptions()
		options.https = true
		options.port = 12111

		err := options.checkConflictingOptions()
		assert.NoError(t, err)
	}

	{
		options := getDefaultOptions()
		options.httpPort = 12111
		options.httpsPort = 12111

		err := options.checkConflictingOptions()
		assert.NoError(t, err)
	}

	{
		options := getDefaultOptions()
		options.httpUnixSocket = "/tmp/stripe-mock.sock"
		options.httpsUnixSocket = "/tmp/stripe-mock-secure.sock"

		err := options.checkConflictingOptions()
		assert.NoError(t, err)
	}

	//
	// Non-specific
	//

	{
		options := getDefaultOptions()
		options.port = 12111
		options.unixSocket = "/tmp/stripe-mock.sock"

		err := options.checkConflictingOptions()
		assert.Equal(t, fmt.Errorf("Please specify only one of -port or -unix"), err)
	}

	//
	// HTTP
	//

	{
		options := getDefaultOptions()
		options.http = true
		options.httpPort = 12111

		err := options.checkConflictingOptions()
		assert.Equal(t, fmt.Errorf("Please don't specify -http when using -http-addr, -http-port, or -http-unix"), err)
	}

	{
		options := getDefaultOptions()
		options.http = true
		options.httpUnixSocket = "/tmp/stripe-mock.sock"

		err := options.checkConflictingOptions()
		assert.Equal(t, fmt.Errorf("Please don't specify -http when using -http-addr, -http-port, or -http-unix"), err)
	}

	{
		options := getDefaultOptions()
		options.port = 12111
		options.httpPort = 12111

		err := options.checkConflictingOptions()
		assert.Equal(t, fmt.Errorf("Please don't specify -port or -unix when using -http-addr, -http-port, or -http-unix"), err)
	}

	{
		options := getDefaultOptions()
		options.unixSocket = "/tmp/stripe-mock.sock"
		options.httpUnixSocket = "/tmp/stripe-mock.sock"

		err := options.checkConflictingOptions()
		assert.Equal(t, fmt.Errorf("Please don't specify -port or -unix when using -http-addr, -http-port, or -http-unix"), err)
	}

	{
		options := getDefaultOptions()
		options.httpAddr = "127.0.0.1:12111"
		options.httpUnixSocket = "/tmp/stripe-mock.sock"

		err := options.checkConflictingOptions()
		assert.Equal(t, fmt.Errorf("Please specify only one of -http-addr, -http-port, or -http-unix"), err)
	}

	{
		options := getDefaultOptions()
		options.httpPort = 12111
		options.httpUnixSocket = "/tmp/stripe-mock.sock"

		err := options.checkConflictingOptions()
		assert.Equal(t, fmt.Errorf("Please specify only one of -http-addr, -http-port, or -http-unix"), err)
	}

	//
	// HTTPS
	//

	{
		options := getDefaultOptions()
		options.https = true
		options.httpsPort = 12111

		err := options.checkConflictingOptions()
		assert.Equal(t, fmt.Errorf("Please don't specify -https when using -https-addr, -https-port, or -https-unix"), err)
	}

	{
		options := getDefaultOptions()
		options.https = true
		options.httpsUnixSocket = "/tmp/stripe-mock.sock"

		err := options.checkConflictingOptions()
		assert.Equal(t, fmt.Errorf("Please don't specify -https when using -https-addr, -https-port, or -https-unix"), err)
	}

	{
		options := getDefaultOptions()
		options.port = 12111
		options.httpsPort = 12111

		err := options.checkConflictingOptions()
		assert.Equal(t, fmt.Errorf("Please don't specify -port or -unix when using -https-addr, -https-port, or -https-unix"), err)
	}

	{
		options := getDefaultOptions()
		options.unixSocket = "/tmp/stripe-mock.sock"
		options.httpsUnixSocket = "/tmp/stripe-mock.sock"

		err := options.checkConflictingOptions()
		assert.Equal(t, fmt.Errorf("Please don't specify -port or -unix when using -https-addr, -https-port, or -https-unix"), err)
	}

	{
		options := getDefaultOptions()
		options.httpsAddr = "127.0.0.1:12111"
		options.httpsUnixSocket = "/tmp/stripe-mock.sock"

		err := options.checkConflictingOptions()
		assert.Equal(t, fmt.Errorf("Please specify only one of -https-addr, -https-port, or -https-unix"), err)
	}

	{
		options := getDefaultOptions()
		options.httpsPort = 12111
		options.httpsUnixSocket = "/tmp/stripe-mock.sock"

		err := options.checkConflictingOptions()
		assert.Equal(t, fmt.Errorf("Please specify only one of -https-addr, -https-port, or -https-unix"), err)
	}
}

// Specify :0 to ask the OS for a free port.
const freePort = 0

func TestOptionsGetHTTPListener(t *testing.T) {
	// Gets a listener when explicitly requested with `-http-addr`.
	{
		options := &options{
			httpAddr: fmt.Sprintf(":%v", freePort),
		}
		listener, err := options.getHTTPListener()
		assert.NoError(t, err)
		assert.NotNil(t, listener)
		listener.Close()
	}

	// Gets a listener when explicitly requested with `-http-port`.
	{
		options := &options{
			httpPort: freePort,
		}
		listener, err := options.getHTTPListener()
		assert.NoError(t, err)
		assert.NotNil(t, listener)
		listener.Close()
	}

	// No listener when HTTPS is explicitly requested, but HTTP is not.
	{
		options := &options{
			httpPort:  -1, // Signals not specified
			httpsPort: freePort,
		}
		listener, err := options.getHTTPListener()
		assert.NoError(t, err)
		assert.Nil(t, listener)
	}

	// Activates on the default HTTP port if no other args provided.
	{
		options := &options{
			httpPortDefault: freePort,
		}
		listener, err := options.getHTTPListener()
		assert.NoError(t, err)
		assert.NotNil(t, listener)
		listener.Close()
	}
}

func TestOptionsGetNonSecureHTTPSListener(t *testing.T) {
	// Gets a listener when explicitly requested with `-https-addr`.
	{
		options := &options{
			httpsAddr: fmt.Sprintf(":%v", freePort),
		}
		listener, err := options.getNonSecureHTTPSListener()
		assert.NoError(t, err)
		assert.NotNil(t, listener)
		listener.Close()
	}

	// Gets a listener when explicitly requested with `-https-port`.
	{
		options := &options{
			httpsPort: freePort,
		}
		listener, err := options.getNonSecureHTTPSListener()
		assert.NoError(t, err)
		assert.NotNil(t, listener)
		listener.Close()
	}

	// No listener when HTTP is explicitly requested, but HTTPS is not.
	{
		options := &options{
			httpPort:  freePort,
			httpsPort: -1, // Signals not specified
		}
		listener, err := options.getNonSecureHTTPSListener()
		assert.NoError(t, err)
		assert.Nil(t, listener)
	}

	// No listener when HTTP is explicitly requested with the old `-port`
	// option.
	{
		options := &options{
			httpsPort: -1, // Signals not specified
			port:      freePort,
		}
		listener, err := options.getNonSecureHTTPSListener()
		assert.NoError(t, err)
		assert.Nil(t, listener)
	}

	// Activates on the default HTTPS port if no other args provided.
	{
		options := &options{
			httpsPortDefault: freePort,
		}
		listener, err := options.getNonSecureHTTPSListener()
		assert.NoError(t, err)
		assert.NotNil(t, listener)
		listener.Close()
	}
}

package param

import (
	"bytes"
	"mime/multipart"
	"net/http"
	"net/http/httptest"
	"testing"

	assert "github.com/stretchr/testify/require"
)

func TestParseParams_Get(t *testing.T) {
	req := httptest.NewRequest(http.MethodGet, "/?query_param=query_val", nil)
	params, err := ParseParams(req)
	assert.NoError(t, err)
	assert.Equal(t, map[string]interface{}{
		"query_param": "query_val",
	}, params)
}

func TestParseParams_Form(t *testing.T) {
	// Basic form in the request body.
	{
		req := httptest.NewRequest(http.MethodPost, "/",
			bytes.NewBufferString("body_param=body_val"))
		params, err := ParseParams(req)
		assert.NoError(t, err)
		assert.Equal(t, map[string]interface{}{
			"body_param": "body_val",
		}, params)
	}

	// Requests with a form body should also include values from the query
	// string, if any were sent.
	{
		req := httptest.NewRequest(http.MethodPost, "/?query_param=query_val",
			bytes.NewBufferString("body_param=body_val"))
		params, err := ParseParams(req)
		assert.NoError(t, err)
		assert.Equal(t, map[string]interface{}{
			"body_param":  "body_val",
			"query_param": "query_val",
		}, params)
	}
}

func TestParseParams_MultipartForm(t *testing.T) {
	var b bytes.Buffer
	w := multipart.NewWriter(&b)
	assert.NoError(t, w.WriteField("foo", "bar"))
	assert.NoError(t, w.Close())

	req := httptest.NewRequest(http.MethodPost, "/", bytes.NewReader(b.Bytes()))
	req.Header.Set("Content-Type", w.FormDataContentType())

	params, err := ParseParams(req)
	assert.NoError(t, err)
	assert.Equal(t, map[string]interface{}{
		"foo": "bar",
	}, params)
}

// Differs from the above by sending a value as a file instead of as just a
// basic multipart parameter. This more accurately represents what a file
// upload would look like.
func TestParseParams_MultipartFormFromFile(t *testing.T) {
	var b bytes.Buffer
	w := multipart.NewWriter(&b)
	fieldW, err := w.CreateFormFile("foo", "foo.txt")
	assert.NoError(t, err)
	_, err = fieldW.Write([]byte("bar"))
	assert.NoError(t, err)
	assert.NoError(t, w.Close())

	req := httptest.NewRequest(http.MethodPost, "/", bytes.NewReader(b.Bytes()))
	req.Header.Set("Content-Type", w.FormDataContentType())

	params, err := ParseParams(req)
	assert.NoError(t, err)
	assert.Equal(t, map[string]interface{}{
		"foo": "bar",
	}, params)
}

package spec

import (
	"testing"

	assert "github.com/stretchr/testify/require"
)

func TestBuildQuerySchema(t *testing.T) {
	// Handles a normal case
	{
		operation := &Operation{
			Parameters: []*Parameter{
				{
					In:   ParameterQuery,
					Name: "name",
					Schema: &Schema{
						Type: TypeString,
					},
				},
			},
		}
		schema := BuildQuerySchema(operation)

		assert.Nil(t, schema.AdditionalProperties)
		assert.Equal(t, false, schema.AdditionalPropertiesAllowed)
		assert.Equal(t, 1, len(schema.Properties))
		assert.Equal(t, 0, len(schema.Required))

		paramSchema := schema.Properties["name"]
		assert.Equal(t, TypeString, paramSchema.Type)
	}

	// A non-query parameter
	{
		operation := &Operation{
			Parameters: []*Parameter{
				{
					In:   ParameterPath,
					Name: "name",
				},
			},
		}
		schema := BuildQuerySchema(operation)

		assert.Equal(t, 0, len(schema.Properties))
	}

	// A required parameter
	{
		operation := &Operation{
			Parameters: []*Parameter{
				{
					In:       ParameterQuery,
					Name:     "name",
					Required: true,
					Schema: &Schema{
						Type: TypeString,
					},
				},
			},
		}
		schema := BuildQuerySchema(operation)

		assert.Equal(t, []string{"name"}, schema.Required)
	}

	// A query parameter with no schema
	{
		operation := &Operation{
			Parameters: []*Parameter{
				{
					In:   ParameterQuery,
					Name: "name",
				},
			},
		}
		schema := BuildQuerySchema(operation)

		paramSchema := schema.Properties["name"]
		assert.Equal(t, TypeObject, paramSchema.Type)
	}
}

package spec

import (
	"testing"

	assert "github.com/stretchr/testify/require"
)

func TestValidator_Simple(t *testing.T) {
	schema := Schema{
		Type: "string",
	}
	v, err := GetValidatorForOpenAPI3Schema(&schema, nil)
	assert.NoError(t, err)
	assert.NoError(t, v.Validate("hello"))
	assert.Error(t, v.Validate(nil))
	assert.Error(t, v.Validate(123))
}

func TestValidator_Nullable(t *testing.T) {
	schema := Schema{
		Type:     "string",
		Nullable: true,
	}
	v, err := GetValidatorForOpenAPI3Schema(&schema, nil)
	assert.NoError(t, err)
	assert.NoError(t, v.Validate("hello"))
	assert.NoError(t, v.Validate(nil))
	assert.Error(t, v.Validate(123))
}

func TestValidator_Reference(t *testing.T) {
	fooSchema := Schema{
		Type: "string",
	}
	components := Components{
		Schemas: map[string]*Schema{
			"foo": &fooSchema,
		},
	}
	componentsForValidation := GetComponentsForValidation(&components)
	fooRefSchema := Schema{
		Ref: "#/components/schemas/foo",
	}
	v, err := GetValidatorForOpenAPI3Schema(&fooRefSchema, componentsForValidation)
	assert.NoError(t, err)
	assert.NoError(t, v.Validate("hello"))
	assert.Error(t, v.Validate(123))
}

package spec

// BuildQuerySchema builds a JSON schema that will be used to validate query
// parameters on the incoming request. Unlike request bodies, OpenAPI puts
// query parameters in a different, non-JSON schema part of an operation.
func BuildQuerySchema(operation *Operation) *Schema {
	schema := &Schema{
		AdditionalProperties:        nil,
		AdditionalPropertiesAllowed: false,
		Properties:                  make(map[string]*Schema),
		Required:                    make([]string, 0),
		Type:                        TypeObject,
	}

	if operation.Parameters == nil {
		return schema
	}

	for _, param := range operation.Parameters {
		if param.In != ParameterQuery {
			continue
		}

		paramSchema := param.Schema
		if paramSchema == nil {
			paramSchema = &Schema{Type: TypeObject}
		}
		schema.Properties[param.Name] = paramSchema

		if param.Required {
			schema.Required = append(schema.Required, param.Name)
		}
	}

	return schema
}

package spec

import (
	"encoding/json"
	"testing"

	assert "github.com/stretchr/testify/require"
)

func TestUnmarshal_Simple(t *testing.T) {
	data := []byte(`{"type": "string"}`)
	var schema Schema
	err := json.Unmarshal(data, &schema)
	assert.NoError(t, err)
	assert.Equal(t, "string", schema.Type)
}

func TestUnmarshal_ObjectWithAdditionalProperties(t *testing.T) {
	data := []byte(`{
		"type": "object",
		"additionalProperties": {
			"properties": {
				"prop": {
					"type": "number"
				}
			},
			"type": "object"
		}
	}`)
	var schema Schema
	err := json.Unmarshal(data, &schema)
	assert.NoError(t, err)
	assert.Equal(t, "object", schema.Type)
	assert.True(t, schema.AdditionalPropertiesAllowed)
	assert.Equal(t, "object", schema.AdditionalProperties.Type)
	assert.Equal(t, 1, len(schema.AdditionalProperties.Properties))
}

func TestUnmarshal_ObjectWithAdditionalPropertiesFalse(t *testing.T) {
	data := []byte(`{
		"type": "object",
		"additionalProperties": false
	}`)
	var schema Schema
	err := json.Unmarshal(data, &schema)
	assert.NoError(t, err)
	assert.Equal(t, "object", schema.Type)
	assert.False(t, schema.AdditionalPropertiesAllowed)
	assert.Nil(t, schema.AdditionalProperties)
}

func TestUnmarshal_ObjectWithAdditionalPropertiesDefault(t *testing.T) {
	data := []byte(`{
		"type": "object"
	}`)
	var schema Schema
	err := json.Unmarshal(data, &schema)
	assert.NoError(t, err)
	assert.Equal(t, "object", schema.Type)
	assert.True(t, schema.AdditionalPropertiesAllowed)
	assert.Nil(t, schema.AdditionalProperties)
}

func TestUnmarshal_UnsupportedField(t *testing.T) {
	// We don't support 'const'
	data := []byte(`{const: "hello"}`)
	var schema Schema
	err := json.Unmarshal(data, &schema)
	assert.Error(t, err)
}

package spec

import (
	"encoding/json"
	"fmt"
)

//
// Public values
//

// A set of constants for the different types of possible OpenAPI parameters.
const (
	ParameterPath  = "path"
	ParameterQuery = "query"
)

// A set of constant for the named types available in JSON Schema.
const (
	TypeArray   = "array"
	TypeBoolean = "boolean"
	TypeInteger = "integer"
	TypeNumber  = "number"
	TypeObject  = "object"
	TypeString  = "string"
)

//
// Public types
//

// Components is a struct for the components section of an OpenAPI
// specification.
type Components struct {
	Schemas map[string]*Schema `json:"schemas"`
}

// ExpansionResources is a struct for possible expansions in a resource.
type ExpansionResources struct {
	OneOf []*Schema `json:"oneOf"`
}

// Fixtures is a struct for a set of companion fixtures for an OpenAPI
// specification.
type Fixtures struct {
	Resources map[ResourceID]interface{} `json:"resources"`
}

// HTTPVerb is a type for an HTTP verb like GET, POST, etc.
type HTTPVerb string

// Info is the `info` portion of an OpenAPI specification that contains meta
// information about it.
type Info struct {
	// Version is the Stripe API version represented in the specification. It
	// takes a date-based form like `2019-02-19`.
	Version string `json:"version"`
}

// This is a list of fields that either we handle properly or we're confident
// it's safe to ignore. If a field not in this list appears in the OpenAPI spec,
// then we'll get an error so we remember to update stripe-mock to support it.
var supportedSchemaFields = []string{
	"$ref",
	"additionalProperties",
	"anyOf",
	"description",
	"enum",
	"format",
	"items",
	"maxLength",
	"nullable",
	"pattern",
	"properties",
	"required",
	"title",
	"type",
	"x-expandableFields",
	"x-expansionResources",
	"x-resourceId",

	// This is currently being used to store additional metadata for our SDKs. It's
	// passed through our Spec and should be ignored
	"x-stripeResource",
	"x-stripeOperations",
	"x-stripeParam",
	"x-stripeEvent",
	"x-stripeEnum",
	"x-stripeMostCommon",
	// This isn't used in our SDK, but is additional metadata unnecessary for
	// stripe-mock.
	"deprecated",

	// This is currently a hint for the server-side so I haven't included it in
	// Schema yet. If we do start validating responses that come out of
	// stripe-mock, we may need to observe this as well.
	"x-stripeBypassValidation",

	// A stable identifier for schema elements, used for tracking across spec
	// versions. Not needed by stripe-mock.
	"x-stableId",
}

// Schema is a struct representing a JSON schema.
type Schema struct {
	// AdditionalProperties is either a nil to indicate that no additional
	// properties in the object are allowed (beyond what's in Properties), or a
	// JSON schema that describes the expected format of any additional properties.
	AdditionalProperties        *Schema `json:"-"`
	AdditionalPropertiesAllowed bool
	AnyOf                       []*Schema          `json:"anyOf,omitempty"`
	Enum                        []interface{}      `json:"enum,omitempty"`
	Format                      string             `json:"format,omitempty"`
	Items                       *Schema            `json:"items,omitempty"`
	MaxLength                   int                `json:"maxLength,omitempty"`
	Nullable                    bool               `json:"nullable,omitempty"`
	Pattern                     string             `json:"pattern,omitempty"`
	Properties                  map[string]*Schema `json:"properties,omitempty"`
	Required                    []string           `json:"required,omitempty"`
	Type                        string             `json:"type,omitempty"`

	// Ref is populated if this JSON Schema is actually a JSON reference, and
	// it defines the location of the actual schema definition.
	Ref string `json:"$ref,omitempty"`

	XExpandableFields   *[]string           `json:"x-expandableFields,omitempty"`
	XExpansionResources *ExpansionResources `json:"x-expansionResources,omitempty"`
	XResourceID         string              `json:"x-resourceId,omitempty"`
}

func (s *Schema) String() string {
	js, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		panic(err)
	}
	return string(js)
}

// UnmarshalJSON is a custom JSON unmarshaling implementation for Schema that
// provides better error messages instead of silently ignoring fields.
func (s *Schema) UnmarshalJSON(data []byte) error {
	var rawFields map[string]interface{}
	err := json.Unmarshal(data, &rawFields)
	if err != nil {
		return err
	}

	additionalPropertiesValue := rawFields["additionalProperties"]

	for _, supportedField := range supportedSchemaFields {
		delete(rawFields, supportedField)
	}
	for unsupportedField := range rawFields {
		return fmt.Errorf(
			"unsupported field in JSON schema: '%s'", unsupportedField)
	}

	// Define a second type that's identical to Schema, but distinct, so that when
	// we call json.Unmarshal it will call the default implementation of
	// unmarshalling a Schema object instead of recursively calling this
	// UnmarshalJSON function again.
	type schemaAlias Schema
	var inner schemaAlias
	err = json.Unmarshal(data, &inner)
	if err != nil {
		return err
	}
	*s = Schema(inner)

	additionalPropertiesBool, ok := additionalPropertiesValue.(bool)

	// AdditionalProperties can be a `false` or `Schema` object for convenience turn
	// load bool and schema into different fields
	if ok {
		s.AdditionalPropertiesAllowed = additionalPropertiesBool
		return nil
	} else {
		s.AdditionalPropertiesAllowed = true
	}

	if additionalPropertiesValue != nil {
		type additionalProperties struct {
			AdditionalProperties *Schema `json:"additionalProperties,omitempty"`
		}
		var addProps additionalProperties
		err = json.Unmarshal(data, &addProps)
		if err != nil {
			return err
		}

		s.AdditionalProperties = addProps.AdditionalProperties
	}

	return nil
}

// MediaType is a struct bucketing a request or response by media type in an
// OpenAPI specification.
type MediaType struct {
	Schema *Schema `json:"schema"`
}

// Operation is a struct representing a possible HTTP operation in an OpenAPI
// specification.
type Operation struct {
	Description string                  `json:"description"`
	OperationID string                  `json:"operation_id"`
	Parameters  []*Parameter            `json:"parameters"`
	RequestBody *RequestBody            `json:"requestBody"`
	Responses   map[StatusCode]Response `json:"responses"`
}

// Parameter is a struct representing a request parameter to an HTTP operation
// in an OpenAPI specification.
type Parameter struct {
	Description string  `json:"description"`
	In          string  `json:"in"`
	Name        string  `json:"name"`
	Required    bool    `json:"required"`
	Schema      *Schema `json:"schema"`
}

// Path is a type for an HTTP path in an OpenAPI specification.
type Path string

// RequestBody is a struct representing the body of a request in an OpenAPI
// specification.
type RequestBody struct {
	Content  map[string]MediaType `json:"content"`
	Required bool                 `json:"required"`
}

// Response is a struct representing the response of an HTTP operation in an
// OpenAPI specification.
type Response struct {
	Description string               `json:"description"`
	Content     map[string]MediaType `json:"content"`
}

// ResourceID is a type for the ID of a response resource in an OpenAPI
// specification.
type ResourceID string

// Spec is a struct representing an OpenAPI specification.
type Spec struct {
	Components Components                       `json:"components"`
	Info       *Info                            `json:"info"`
	Paths      map[Path]map[HTTPVerb]*Operation `json:"paths"`
}

// StatusCode is a type for the response status code of an HTTP operation in an
// OpenAPI specification.
type StatusCode string

package server

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io/ioutil"
