					},
				},
			},
			verbose,
		}
		data, err := generator.Generate(&GenerateParams{
			Schema: &spec.Schema{
				Type: "object",
				Properties: map[string]*spec.Schema{
					"charges_list": listSchemaWithPlaceholder,
				},
